    // 根据 drawInfo 计算抓牌起始位置
    const drawInfo = this.gameState.drawInfo;
    if (drawInfo && drawInfo.drawDirection) {
        // 座位与方位映射
        const seatToDirection = { 1: '东', 2: '南', 3: '西', 4: '北' };
        // 方位到数组偏移的映射（牌墙按 东17墩 南17墩 西17墩 北17墩 排列，逆时针沿牌桌）
        const directionToOffset = { 1: 0, 2: 17, 3: 34, 4: 51 };
        // 抓牌方向从1往17，第1墩对应偏移0，第17墩对应偏移16
        // drawPile 是起始墩号（1, 2, ..., 17）
        const pileOffset = drawInfo.drawPile - 1; // 第1墩偏移0，第17墩偏移16
        let startIndex = (directionToOffset[drawInfo.drawDirection] + pileOffset) * 2;
        // 确保索引在有效范围内
        startIndex = Math.max(0, Math.min(startIndex, this.gameState.deck.length - 1));

        // 重排牌堆，使抓牌位置成为新的牌顶
        if (startIndex > 0) {
            const before = this.gameState.deck.slice(0, startIndex);
            const after = this.gameState.deck.slice(startIndex);
            this.gameState.deck = [...after, ...before];
            console.log(`牌堆重排：从${seatToDirection[drawInfo.drawDirection]}方第${drawInfo.drawPile}墩（索引${startIndex}）开始，剩余${this.gameState.deck.length}张`);
        }
    }

    // 初始化牌墙状态：每个方位17墩
    this.gameState.wallState = { 1: 17, 2: 17, 3: 17, 4: 17 };

    // 顺时针发牌顺序：东(1)→南(4)→西(3)→北(2)
    // playerIds 是 [座位1, 座位2, 座位3, 座位4] = [东, 北, 西, 南]
    // 顺时针顺序：东→南→西→北 = [座位1, 座位4, 座位3, 座位2]
    const clockwiseIds = [
        playerIds[0], // 座位1(东-庄家)
        playerIds[3], // 座位4(南)
        playerIds[2], // 座位3(西)
        playerIds[1]  // 座位2(北)
    ];

    // 发牌：每人4张×3轮，然后每人1张，庄家多1张
    // 每人4张×3轮（顺时针顺序）- 相当于每人2墩×3轮
    for (let round = 0; round < 3; round++) {
        for (const pid of clockwiseIds) {
            for (let i = 0; i < 4; i++) {
                const card = this.gameState.deck.pop();
                if (card) this.gameState.hands[pid].push(card);
            }
        }
    }

    // 每人1张（顺时针顺序）
    for (const pid of clockwiseIds) {
        const card = this.gameState.deck.pop();
        if (card) this.gameState.hands[pid].push(card);
    }

    // 庄家多拿1张
    const dealerPid = playerIds[this.gameState.dealer];
    const extraCard = this.gameState.deck.pop();
    if (extraCard) this.gameState.hands[dealerPid].push(extraCard);

    // 更新牌墙状态（根据实际抓取的牌数）
    this.updateWallState();

    // 庄家先出牌
    this.gameState.currentPlayer = this.gameState.dealer;

    // 排序手牌
    for (const pid of playerIds) {
        this.sortHand(pid);
    }

    console.log(`牌桌${this.tableNumber} 第${this.currentRound}局开始，庄家座位: ${this.gameState.dealerSeat}，万能牌: ${cardName(this.gameState.wildCard)}`);
    console.log(`发牌完成，牌堆剩余: ${this.gameState.deck.length}张，牌墙状态: ${JSON.stringify(this.gameState.wallState)}`);

    // 直接发送游戏状态（删除发牌动画）
    this.broadcastGameState();
    // 检查是否轮到AI出牌
    this.checkAITurn();
}

