    }

    // 获取第二次掷骰子的人（根据第一次骰子点数和，逆时针数）
    getSecondRoller(firstSum) {
        const playerIds = this.getSortedPlayerIds();
        const firstRollerIndex = playerIds.indexOf(this.diceState.firstRoll.playerId);

        // playerIds 是 [座位1, 座位2, 座位3, 座位4]（顺时针：东→南→西→北）
        // 逆时针顺序：东(0)→北(3)→西(2)→南(1)→东(0)
        // 逆时针移动一步 = 索引 -1（或 +3 mod 4）
        // 数firstSum步，从1开始数（所以-1）
        const secondRollerIndex = (firstRollerIndex - (firstSum - 1) % 4 + 4) % 4;
        return playerIds[secondRollerIndex];
    }

    // 掷骰子
    rollDice(playerId, values) {
        console.log(`rollDice 被调用: playerId=${playerId}, values=${JSON.stringify(values)}, currentRoller=${this.diceState.currentRoller}, rollPhase=${this.diceState.rollPhase}`);

