/* 展示区 */
.showed-area {
    display: flex;
    gap: 5px;
    margin: 5px 0;
    flex-wrap: wrap;
    justify-content: center;
}

.showed-card {
    width: 30px;
    height: 40px;
    background: #fff;
    border-radius: 3px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    color: #333;
    overflow: hidden;
}

.showed-card.fa {
    background: #FFD700;
}

.showed-card.gang {
    background: #90EE90;
}

/* 手牌区域 */
.hand-area {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 1px;
    padding: 10px;
    background: linear-gradient(180deg, #1a472a 0%, #0d2818 100%);

