/* 对手手牌背面 */
.opponent-hand {
    display: flex;
    gap: 2px;
    justify-content: center;
    margin: 5px 0;
    min-height: 30px;
}

.opponent-card-back {
    width: 20px;
    height: 28px;
    background: linear-gradient(135deg, #2c5530 0%, #1a3a1f 100%);
    border: 1px solid #3d6b42;
    border-radius: 2px;
    box-shadow: 1px 1px 2px rgba(0,0,0,0.3);
}

.opponent-card-back.small {
    width: 16px;
    height: 22px;
}

/* 上家手牌横向排列 */
.player-area.top .opponent-hand {
    flex-direction: row;
}

