        }
    }

    // 每人1张
    for (const pid of clockwiseIds) {
        const card = drawCardSkipShown();
        if (card) this.gameState.hands[pid].push(card);
        dealStep++;
        updateWallForDraw(1);
        broadcastDealProgress(dealStep, totalSteps);
        await new Promise(r => setTimeout(r, 100));
