    // 庄家多拿1张
    const dealerPid = playerIds[this.gameState.dealer];
    const extraCard = drawCardSkipShown();
    if (extraCard) this.gameState.hands[dealerPid].push(extraCard);
    dealStep++;
    updateWallForDraw(1);
    broadcastDealProgress(dealStep, totalSteps);

