// 广播摸牌动画
broadcastDrawAnimation(playerId) {
    const player = this.players.get(playerId);
    const seatNum = player ? player.seatNum : 0;

    const message = JSON.stringify({
        type: 'drawAnimation',
        data: {
            playerId,
            seatNum,
            wallState: this.gameState.wallState,
            deckCount: this.gameState.deck.length
        }
    });

    for (const p of this.players.values()) {
        if (p.ws && p.ws.readyState === WebSocket.OPEN) {
            p.ws.send(message);
        }
    }
}

// 更新牌墙状态
updateWallState() {
    // 计算已抓取的牌数
    // 初始136张，如果亮牌已跳过则牌堆少1张亮牌
    const shownCardRemoved = this.gameState.shownCardSkipped ? 1 : 0;
    const initialCards = 136 - shownCardRemoved; // 总牌数减去已移除的亮牌
    const remainingCards = this.gameState.deck.length;

