  1815→                }
  1816→            }
  1817→            if (allDisconnected && !table.gameState.started) {
  1818→                tables.delete(tableId);
  1819→                console.log(`Cleaned up disconnected table: ${tableId}`);
  1820→            }
  1821→        }
  1822→    }
  1823→}, 300000); // 5分钟
  1824→
  1825→// 导出
