        // 保留序号 1 到 (startPile - 1) 和 (startPile + remainingToDraw) 到 17
        const lastDrawn = startPile + remainingToDraw - 1;
        if (startPile > 1) {
            // 前面有保留
            if (lastDrawn < 17) {
                // 后面也有保留
                wallState[drawDir] = {
                    start: 1,
                    count: startPile - 1,
                    endKeep: { start: lastDrawn + 1, count: 17 - lastDrawn }
                };
            } else {
                // 后面没有保留
                wallState[drawDir] = { start: 1, count: startPile - 1 };
            }
        } else {
            // 前面没有保留
            if (lastDrawn < 17) {
                wallState[drawDir] = { start: lastDrawn + 1, count: 17 - lastDrawn };
            } else {
                wallState[drawDir] = { start: 0, count: 0 };
            }
        }
        remainingToDraw = 0;
    }

    // 逆时针处理其他方位
    while (remainingToDraw > 0 && currentDirIdx !== drawIdx) {
        const currentDir = directionOrder[currentDirIdx];

        if (remainingToDraw >= 17) {
            // 这个方位全部被抓
            wallState[currentDir] = { start: 0, count: 0 };
            remainingToDraw -= 17;
        } else {
            // 只抓了一部分，从序号1开始抓 remainingToDraw 墩
            // 保留序号 (remainingToDraw + 1) 到 17
            wallState[currentDir] = { start: remainingToDraw + 1, count: 17 - remainingToDraw };
            remainingToDraw = 0;
        }
        // 逆时针移动
        currentDirIdx = (currentDirIdx + 1) % 4;
    }

    this.gameState.wallState = wallState;
    console.log(`牌墙状态更新: ${JSON.stringify(wallState)}`);
}

